// Referenced LearnOpenGL 
// https://learnopengl.com/Lighting/Basic-Lighting
// https://learnopengl.com/Lighting/Light-casters

// This scene contains: 
// - An animated red point light and a directional light from the side (Phong diffuse and specular)
// - Ambient lighting
// - A green cube with emissive material 
// - Two spheres with cube-mapped reflections

# define M_PI 3.14

//=======================================================================================
vec3 ShadeDirectionalLight(in vec3 albedo, in vec3 normal, in vec3 lightColor, in vec3 hitPos, in vec3 cameraPos)
{
    // Ambient lighting for directional light
    float ambientStrength = 0.1;
    vec3 ambient = ambientStrength * lightColor;

    // Diffuse 
    vec3 norm = normalize(normal);
    vec3 lightDir = normalize(vec3(-1.0, -1.0, -1.0));
    float diff = max(dot(norm, -lightDir), 0.0);
    vec3 diffuse = diff * lightColor;

    // Specular
    float specularStrength = 0.5;
    vec3 viewDir = normalize(cameraPos - hitPos);
    vec3 reflectDir = reflect(lightDir, norm);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
    vec3 specular = specularStrength * spec * lightColor;

    // Return color contribution from directional light
    return (ambient + diffuse + specular) * albedo;
}

//=======================================================================================
vec3 ShadePixel (in vec3 albedo, in vec3 normal, in vec3 lightPos, in vec3 lightColor, in vec3 hitPos, in vec3 cameraPos)
{
    // Ambient lighting
    float ambientStrength = 0.1;
    vec3 ambient = ambientStrength * lightColor;

    // Diffuse 
    vec3 norm = normalize(normal);
    vec3 lightDir = normalize(lightPos - hitPos);
    float diff = max(dot(norm, lightDir), 0.0);
    vec3 diffuse = diff * lightColor;

    // Specular
    float specularStrength = 0.5;
    vec3 viewDir = normalize(cameraPos - hitPos);
    vec3 reflectDir = reflect(-lightDir, norm);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
    vec3 specular = specularStrength * spec * lightColor;

    // Environment mapped reflections
    vec3 rayDir = normalize(hitPos - cameraPos);
    vec3 reflectionDir = reflect(rayDir, norm);
    vec3 cubemapReflectionColor = texture(iChannel0, reflect(rayDir, normal)).rgb;

    float reflectionStrength = 0.3;
    vec3 finalColor = mix((ambient + diffuse + specular) * albedo, cubemapReflectionColor, reflectionStrength);

    return finalColor;
}

//=======================================================================================
vec3 ShadeWithLights(in vec3 albedo, in vec3 normal, in vec3 hitPos, in vec3 cameraPos, in vec3 emissiveColor)
{
    vec3 color = vec3(0.0);

    // Handle point light
    float pointX = 2.0 * sin(M_PI * iTime);
    float pointZ = 2.0 * cos(M_PI * iTime);
    vec3 pointPos = vec3(pointX, 2.0, pointZ);

    color += ShadePixel(albedo, normal, pointPos, vec3(1.0, 0.0, 0.0), hitPos, cameraPos);

    // Handle directional light
    color += ShadeDirectionalLight(albedo, normal, vec3(1.0, 1.0, 1.0), hitPos, cameraPos);

    // Handle emissive material
    color += emissiveColor;

    // Return accumulated color from all lights
    return color; 
}

//=======================================================================================
bool RayIntersectAABox  (in vec3 boxMin, in vec3 boxMax, in vec3 rayPos, in vec3 rayDir, out vec3 hitPos, out vec3 normal, inout float maxTime)
{
    vec3 boxCenter = (boxMin+boxMax)*0.5;
	vec3 roo = rayPos - boxCenter;
    vec3 rad = (boxMax - boxMin)*0.5;

    vec3 m = 1.0/rayDir;
    vec3 n = m*roo;
    vec3 k = abs(m)*rad;

    vec3 t1 = -n - k;
    vec3 t2 = -n + k;

    vec2 time = vec2( max( max( t1.x, t1.y ), t1.z ),
                 min( min( t2.x, t2.y ), t2.z ) );

    // if the time is beyond the maximum allowed bail out (we hit something else first!)
    if (time.x > maxTime)
        return false;

    // if time invalid or we hit from inside, bail out
    if (time.y < time.x || time.x < 0.0)
        return false;

    // calculate surface normal
    hitPos = rayPos + rayDir * time.x;   
    vec3 hitPosRelative = hitPos - boxCenter;
    vec3 hitPosRelativeAbs = abs(hitPosRelative);
    vec3 distToEdge = abs(hitPosRelativeAbs - rad);

    float closestDist = 1000.0;
    for(int axis = 0; axis < 3; ++axis)
    {
        if (distToEdge[axis] < closestDist)
        {
            closestDist = distToEdge[axis];
            normal = vec3(0.0);
            if (hitPosRelative[axis] < 0.0)
                normal[axis] = -1.0;
            else
                normal[axis] = 1.0;
        }
    }        

    // store the collision time as the new max time
    maxTime = time.x;
    return true;
}

//=======================================================================================
bool RayIntersectSphere (in vec4 sphere, in vec3 rayPos, in vec3 rayDir, out vec3 hitPos, out vec3 normal, inout float maxTime)
{
    if (sphere.w <= 0.0)
        return false;

	//get the vector from the center of this circle to where the ray begins.
	vec3 m = rayPos - sphere.xyz;

    //get the dot product of the above vector and the ray's vector
	float b = dot(m, rayDir);

	float c = dot(m, m) - sphere.w * sphere.w;

	//exit if r's origin outside s (c > 0) and r pointing away from s (b > 0)
	if(c > 0.0 && b > 0.0)
		return false;

	//calculate discriminant
	float discr = b * b - c;

	//a negative discriminant corresponds to ray missing sphere
	if(discr < 0.0)
		return false;

	//ray now found to intersect sphere, compute smallest t value of intersection
	float collisionTime = -b - sqrt(discr);

	//if t is negative, ray started inside sphere so clamp t to zero and remember that we hit from the inside
	if(collisionTime < 0.0)
        return false;

    // if the time is beyond the maximum allowed bail out (we hit something else first!)
    if (collisionTime > maxTime)
        return false;

    // store the collision time as the new max time
    maxTime = collisionTime;

	//compute the point of intersection
	hitPos = rayPos + rayDir * collisionTime;    

   	// calculate the normal
	normal = hitPos - sphere.xyz;
	normal = normalize(normal); 

	return true;
}

//=======================================================================================
bool TraceRay (in vec3 rayPos, in vec3 rayDir, inout vec3 pixelColor, out vec3 hitPos, out vec3 normal, in vec3 cameraPos)
{   
    float maxRayHitTime = 1000.0;
    bool hit = false;
    vec3 localHitPos;    
    vec3 localNormal;            
    vec3 albedo;
    vec3 emissiveColor;

	// green box
    if (RayIntersectAABox(vec3(0.4,-0.3,-0.5), vec3(1.4,0.3,0.5), rayPos, rayDir, localHitPos, localNormal, maxRayHitTime))
    {
        hit = true;
        albedo = vec3(0.1, 0.9, 0.1);
        emissiveColor = albedo;
        hitPos = localHitPos;
        normal = localNormal;
    }

    // red sphere
    if (RayIntersectSphere(vec4(-0.4, 0.4, 0.5, 0.5), rayPos, rayDir, localHitPos, localNormal, maxRayHitTime))
    {
        hit = true;
        albedo = vec3(0.9, 0.1, 0.1); 
        hitPos = localHitPos;
        normal = localNormal;
    }

    // blue sphere
    if (RayIntersectSphere(vec4(-0.8, 0.4, -0.75, 0.25), rayPos, rayDir, localHitPos, localNormal, maxRayHitTime))
    {
        hit = true;
        albedo = vec3(0.1, 0.1, 0.9);    
        hitPos = localHitPos;
        normal = localNormal;
    }

    if (!hit)
		return false;

    pixelColor = ShadeWithLights(albedo, normal, hitPos, cameraPos, emissiveColor);
    return true;
}

//=======================================================================================
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{   
    //----- camera setup
    vec2 mouse = iMouse.xy / iResolution.xy;

    vec3 cameraAt = vec3(0.0,0.0,0.0);

    float angleX = iMouse.z > 0.0 ? 6.28 * mouse.x : 0.0;
    float angleY = iMouse.z > 0.0 ? (mouse.y * 6.28) : 0.0;

    vec3 cameraPos	= (vec3(sin(angleX)*cos(angleY), sin(angleY), cos(angleX)*cos(angleY))) * 4.0;

    vec3 cameraFwd  = normalize(cameraAt - cameraPos);
    vec3 cameraLeft  = normalize(cross(normalize(cameraAt - cameraPos), vec3(0.0,sign(cos(angleY)),0.0)));
    vec3 cameraUp   = normalize(cross(cameraLeft, cameraFwd));

    float cameraViewWidth	= 6.0;
    float cameraViewHeight	= cameraViewWidth * iResolution.y / iResolution.x;
    float cameraDistance	= 6.0;  // intuitively backwards!    

	vec2 rawPercent = (fragCoord.xy / iResolution.xy);
	vec2 percent = rawPercent - vec2(0.5,0.5);

	vec3 rayPos;
	vec3 rayTarget;

	// if the mouse button is down do orbit camera
	if( iMouse.z > 0.0 ) {
		rayTarget = (cameraFwd * cameraDistance)
				  + (cameraLeft * percent.x * cameraViewWidth)
		          + (cameraUp * percent.y * cameraViewHeight);

		rayPos = cameraPos;
	}
	// else handle the case of the mouse button not being down
	else {
		rayPos = vec3(0.0,3.0,-3.0);
		vec3 f = normalize(cameraAt - rayPos);
		vec3 l = normalize(cross(f,vec3(0.0,1.0,0.0)));
		vec3 u = normalize(cross(l,f));

		rayTarget = (f * cameraDistance)
				  + (l * percent.x * cameraViewWidth)
		          + (u * percent.y * cameraViewHeight);		
	}

	//----- ray trace
	vec3 rayDir = normalize(rayTarget);

    // initialze ray color to the cube map
    vec3 pixelColor = texture(iChannel0, rayDir).rgb;

    vec3 hitPos, normal;

    // ray trace
    if(TraceRay(rayPos, rayDir, pixelColor, hitPos, normal, rayPos)){
        pixelColor = pow(pixelColor, vec3(1.0/2.2)); 

    }

    // output sRGB corrected pixel
	fragColor = vec4(pixelColor, 1.0);
}

